for key,a in pairs(areas) do P.GatherAreas[key]=a end
for key,a in pairs(nodes) do P.GatherNodeData.areas[key]=a end
for id,n in pairs(npcs) do P.NPCSources[id]=n end
for key,a in pairs(zones) do P.GatherZoneAreas[key]=a end
local function append(list,value)
    for _,v in ipairs(list) do if v==value then return end end
    list[#list+1]=value
end
for _,entries in pairs(P.GatherAtlas) do
    for _,e in ipairs(entries) do
        local patch=patches[e.key]
        if patch then
            e.sources=patch.sources;e.mapKeys=e.mapKeys or {};e.referenceURLs=e.referenceURLs or {}
            for _,key in ipairs(patch.newMapKeys) do append(e.mapKeys,key) end
            for _,s in ipairs(e.sources) do if s.url then append(e.referenceURLs,s.url) end end
            e.searchText=(e.searchText or e.name:lower()).." zephras isle"
            e.sub=(e.sub or "Material"):gsub("%d+ sources",#e.sources.." sources")
            -- Preserve the old fallback list if this entry did not use aggregates.
            local options=P.GatherZoneMaps[e.key]
            if not options then
                options={}
                for _,key in ipairs(e.mapKeys) do
                    if P.GatherAreas[key] and not areas[key] then
                        P.GatherZoneAreas[key]=P.GatherAreas[key];append(options,key)
                    end
                end
                P.GatherZoneMaps[e.key]=options
            end
            append(options,choices[e.item])
        end
    end
end
-- Reference coverage in the first gathering tier; no fabricated route line.
for prof,r in pairs(references) do
    local options=P.GatherVisuals[prof] and P.GatherVisuals[prof][1]
    if options then options[#options+1]=r end
end
